<?php
require_once __DIR__ . '/../includes/bootstrap.php';require_admin();
$type=($_GET['type']??'tips')==='actions'?'actions':'tips';$isTips=$type==='tips';$table=$type;$label=$isTips?'Materi edukasi':'Aksi lingkungan';$pageTitle='Kelola '.$label;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$op=$_POST['op']??'';
 if($op==='delete'){$id=(int)($_POST['id']??0);$stmt=$pdo->prepare("DELETE FROM `$table` WHERE id=?");$stmt->execute([$id]);flash('success',$label.' berhasil dihapus.');header('Location: content.php?type='.$type);exit;}
 if($op==='save'){$id=(int)($_POST['id']??0);$title=trim($_POST['title']??'');$category=trim($_POST['category']??'');$icon=trim($_POST['icon']??'🌱');$summary=trim($_POST['summary']??'');$body=trim($_POST['body']??'');$duration=trim($_POST['duration']??'');$published=isset($_POST['is_published'])?1:0;
 if($title===''||$category===''||$summary===''||($isTips&&$body==='')||(!$isTips&&$duration==='')){flash('error','Lengkapi semua kolom wajib.');header('Location: content.php?type='.$type.($id?'&edit='.$id:''));exit;}
 if($isTips){if($id){$stmt=$pdo->prepare("UPDATE tips SET title=?,category=?,icon=?,summary=?,body=?,is_published=? WHERE id=?");$stmt->execute([$title,$category,$icon,$summary,$body,$published,$id]);}else{$stmt=$pdo->prepare("INSERT INTO tips(title,category,icon,summary,body,is_published) VALUES(?,?,?,?,?,?)");$stmt->execute([$title,$category,$icon,$summary,$body,$published]);}}
 else {if($id){$stmt=$pdo->prepare("UPDATE actions SET title=?,category=?,icon=?,summary=?,description=?,duration=?,is_published=? WHERE id=?");$stmt->execute([$title,$category,$icon,$summary,$body,$duration,$published,$id]);}else{$stmt=$pdo->prepare("INSERT INTO actions(title,category,icon,summary,description,duration,is_published) VALUES(?,?,?,?,?,?,?)");$stmt->execute([$title,$category,$icon,$summary,$body,$duration,$published]);}}
 flash('success',$label.' berhasil disimpan.');header('Location: content.php?type='.$type);exit;
 }}
$editing=null;if(isset($_GET['edit'])){$st=$pdo->prepare("SELECT * FROM `$table` WHERE id=?");$st->execute([(int)$_GET['edit']]);$editing=$st->fetch();}
$items=$pdo->query("SELECT * FROM `$table` ORDER BY created_at DESC")->fetchAll();
require __DIR__ . '/../includes/header.php';
?>
<section class="admin-shell"><aside class="admin-sidebar"><span class="eyebrow">ADMIN CONSOLE</span><h2>Kelola konten</h2><a class="admin-link" href="index.php">▦ &nbsp; Ringkasan</a><a class="admin-link <?=$isTips?'active':''?>" href="content.php?type=tips">✳ &nbsp; Materi edukasi</a><a class="admin-link <?=!$isTips?'active':''?>" href="content.php?type=actions">♻ &nbsp; Aksi lingkungan</a><a class="admin-link" href="reports.php">☷ &nbsp; Laporan masuk</a><a class="admin-link" href="logout.php">↪ &nbsp; Keluar</a><a class="admin-back" href="../index.php">← Lihat situs</a></aside><div class="admin-main"><div class="admin-heading"><div><span class="eyebrow">MANAJEMEN KONTEN</span><h1><?=e($label)?></h1><p>Tambah, perbarui, dan atur publikasi konten.</p></div></div><div class="editor-panel"><h2><?=$editing?'Edit konten':'Tambah konten baru'?></h2><form method="post" class="editor-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="op" value="save"><input type="hidden" name="id" value="<?=(int)($editing['id']??0)?>"><div class="editor-grid"><div class="field"><label>Judul *</label><input name="title" required maxlength="180" value="<?=e($editing['title']??'')?>"></div><div class="field"><label>Kategori *</label><input name="category" required maxlength="80" value="<?=e($editing['category']??'')?>" placeholder="Contoh: Pengelolaan sampah"></div><div class="field"><label>Ikon / emoji</label><input name="icon" maxlength="20" value="<?=e($editing['icon']??'🌱')?>"></div><div class="field"><label>Ringkasan *</label><input name="summary" required maxlength="220" value="<?=e($editing['summary']??'')?>"></div><?php if(!$isTips):?><div class="field"><label>Durasi *</label><input name="duration" required maxlength="80" value="<?=e($editing['duration']??'')?>" placeholder="Contoh: 10 menit"></div><?php endif;?><div class="field full"><label><?=$isTips?'Isi materi *':'Deskripsi aksi *'?></label><textarea name="body" rows="4" required><?=e($editing[$isTips?'body':'description']??'')?></textarea></div></div><label class="check-label"><input type="checkbox" name="is_published" value="1" <?=!isset($editing['is_published'])||(int)$editing['is_published']===1?'checked':''?>> Tampilkan di situs publik</label><div class="form-actions"><button class="btn btn-primary" type="submit">Simpan konten ↗</button><?php if($editing):?><a class="btn btn-quiet" href="content.php?type=<?=$type?>">Batal edit</a><?php endif;?></div></form></div><div class="admin-table-wrap"><div class="table-title"><div><h2>Daftar konten</h2><p><?=count($items)?> item tersimpan</p></div></div><div class="table-scroll"><table><thead><tr><th>Konten</th><th>Kategori</th><th>Publikasi</th><th>Aksi</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><b><?=e($item['icon'])?> <?=e($item['title'])?></b><small><?=e(excerpt($item['summary'],95))?></small></td><td><?=e($item['category'])?></td><td><span class="status <?=$item['is_published']?'status-selesai':'status-baru'?>"><?=$item['is_published']?'Terbit':'Draft'?></span></td><td><div class="table-actions"><a href="content.php?type=<?=$type?>&edit=<?=(int)$item['id']?>">Edit</a><form method="post" onsubmit="return confirm('Hapus konten ini?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="op" value="delete"><input type="hidden" name="id" value="<?=(int)$item['id']?>"><button type="submit">Hapus</button></form></div></td></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="4" class="table-empty">Belum ada konten.</td></tr><?php endif;?></tbody></table></div></div></div></section>
